 const assignedToOther=(playerId,teamIndex)=>teams.some((_,i)=>i!==teamIndex&&(form.elements[`teamGoalie${i}`].value===playerId||form.querySelector(`input[name="teamPlayers${i}"][value="${CSS.escape(playerId)}"]`)?.checked));
 const refreshTeamOptions=()=>{document.querySelectorAll('[data-team-picker]').forEach(picker=>{const i=Number(picker.dataset.teamPicker),term=playerKey(document.querySelector(`[data-team-filter="${i}"]`).value);picker.querySelectorAll('.team-player-option').forEach(label=>{const box=label.querySelector('input'),claimed=assignedToOther(box.value,i)||teams.some((_,teamIndex)=>form.elements[`teamGoalie${teamIndex}`].value===box.value);label.hidden=claimed||!label.dataset.playerSearch.includes(term)})});document.querySelectorAll('[name^="teamGoalie"]').forEach(select=>{const i=Number(select.name.replace('teamGoalie',''));[...select.options].forEach(option=>{option.disabled=!!option.value&&(assignedToOther(option.value,i)||teams.some((_,teamIndex)=>form.querySelector(`input[name="teamPlayers${teamIndex}"][value="${CSS.escape(option.value)}"]`)?.checked))})});teams.forEach((_,i)=>{document.querySelector(`[data-team-count="${i}"]`).textContent=`${document.querySelectorAll(`input[name="teamPlayers${i}"]:checked`).length}/${8} jogadores`})};
 document.querySelector('#randomizeTeams').onclick=()=>{const shuffle=items=>{const copy=items.slice();for(let i=copy.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]]}return copy};const unique=items=>[...new Map(items.map(p=>[p.id,p])).values()];const linePlayers=shuffle(unique(g.players.filter(isFieldPlayer).map(entry=>state.players.find(player=>player.id===entry.playerId)||findTeamPlayer(entry.name)).filter(Boolean)));const goalkeepers=shuffle(unique(g.players.filter(entry=>entry.position==='Goleiro'&&entry.participationConfirmed!==false).map(entry=>state.players.find(player=>player.id===entry.playerId)||findTeamPlayer(entry.name)).filter(Boolean)));form.querySelectorAll('input[name^="teamPlayers"]').forEach(input=>input.checked=false);if(goalkeepers.length)teams.forEach((_,i)=>{document.querySelector('[name="teamGoalie'+i+'"]').value=''});const counts=teams.map(()=>0);let pending=0;for(const player of linePlayers){const maxPerTeam=8;const available=teams.map((_,i)=>i).filter(i=>counts[i]<maxPerTeam);if(!available.length){pending++;continue}const min=Math.min(...available.map(i=>counts[i])),balanced=available.filter(i=>counts[i]===min),teamIndex=balanced[Math.floor(Math.random()*balanced.length)],box=form.querySelector('input[name="teamPlayers'+teamIndex+'"][value="'+CSS.escape(player.id)+'"]');if(box){box.checked=true;counts[teamIndex]++}else pending++}goalkeepers.slice(0,teams.length).forEach((player,i)=>{const select=document.querySelector('[name="teamGoalie'+i+'"]');if(select&&[...select.options].some(option=>option.value===player.id))select.value=player.id});form.elements.teamAssignmentMode.value='random';refreshTeamOptions();toast(pending?'Sorteio feito. '+pending+' inscritos ficaram aguardando uma vaga de time.':'Sorteio concluído. Confira e salve os times.');};document.querySelectorAll('[data-team-filter]').forEach(input=>input.oninput=refreshTeamOptions);
