document.addEventListener('submit',async e=>{
 if(e.target.id==='playerProfileForm'){e.preventDefault();const form=e.target,button=form.querySelector('button[type="submit"]'),displayName=form.elements.displayName.value.trim(),displayNickname=form.elements.displayNickname.value.trim();if(!displayName){toast('Informe seu nome completo.');return}if(button)button.disabled=true;try{await updateMyPlayerProfile(currentUser.uid,displayName,displayNickname);currentPlayerData={...currentPlayerData,displayName,displayNickname};renderPlayerPage();toast('Nome e apelido salvos.')}catch(error){toast(error.message||'Não foi possível salvar seu apelido. Confira as regras do Firestore.')}finally{if(button)button.disabled=false}return}if(e.target.id!=='loginForm')return;e.preventDefault();
 const form=e.target,button=e.submitter||form.querySelector('button[type=submit]');button.disabled=true;button.textContent='Aguarde…';
 try{if(form.dataset.kind==='admin'){await signInAdmin(form.elements.email.value.trim(),form.elements.password.value)}else{const identifier=form.elements.identifier.value.trim(),firstName=identifier.split(/\s+/)[0],phone=phoneDigits(form.elements.phone.value);if(!identifier)throw new Error('Informe seu primeiro nome, nome completo ou apelido.');if(!((phone.length>=9&&phone.length<=11)||phone==='123456'))throw new Error('Informe os 9 números do telefone local, sem DDD. Se sua senha for provisória, use 123456.');pendingPlayerIdentity={firstName,phone};if(button.value==='request')await registerPlayer(firstName,phone,identifier,'');else await signInPlayer(identifier,phone)}}
 catch(err){const adminLogin=form.dataset.kind==='admin';const message=err.code==='auth/email-already-in-use'?'Este primeiro acesso já foi solicitado. Escolha Entrar.':err.code==='auth/invalid-credential'||err.code==='auth/user-not-found'||err.code==='auth/wrong-password'?(adminLogin?'E-mail ou senha administrativa incorretos. Confirme o cadastro em Firebase Authentication → Usuários.':'Nome, apelido ou telefone incorreto. Para primeiro acesso, use o botão correspondente.'):err.code==='auth/operation-not-allowed'?'Ative o provedor E-mail/senha em Firebase Authentication → Método de login.':err.code==='auth/weak-password'?'Não foi possível cadastrar a senha.':err.code==='permission-denied'?'O Firestore negou o acesso. Publique as regras atualizadas do projeto e tente novamente.':err.message||'Não foi possível entrar. Verifique os dados.';renderLogin(message)}

});

